console.log('----------------\n');

if (response.functionCalls && response.functionCalls.length > 0) {
  const fc = response.functionCalls[0];
  console.log(`→ Gemini が "${fc.name}" を呼びたがっている`);
  console.log(`  args: ${JSON.stringify(fc.args)}`);

  // アプリ側でツールを実行
