      response.functionCalls.map(async (fc) => {
        const result = await readFileTool.execute(fc.args as { path: string });
        return createPartFromFunctionResponse(fc.id ?? "", fc.name ?? "", { output: result });
      }),
    );

    // 結果を渡して続きを聞く
    currentInput = results;
  }
}
```

