// Step 3: Gemini API に自作ツール（read_file）を渡す
// Gemini はファイルシステムにアクセスできない。
// 「read_file を呼びたい」という JSON を返してくるので、
// アプリ側でファイルを読んで結果を返す。ループはまだない（1往復のみ）。

import 'dotenv/config';
import { GoogleGenAI, Type, createPartFromFunctionResponse } from '@google/genai';
import * as fs from 'node:fs/promises';

const ai = new GoogleGenAI({ apiKey: process.env.GEMINI_API_KEY! });

// 自作ツールの定義（Gemini に渡す「仕様書」）
// execute は Gemini には渡されない。アプリ側だけが持つ。
const readFileTool = {
  declaration: {
    name: 'read_file',
    description: 'ファイルの内容を読み込んで返す',
    parameters: {
      type: Type.OBJECT,
      properties: {
        path: { type: Type.STRING, description: 'ファイルパス' },
      },
      required: ['path'],
    },
  },
  execute: async (args: { path: string }) => {
    return await fs.readFile(args.path, 'utf-8');
  },
};

const chat = ai.chats.create({
  model: 'gemini-2.5-flash-lite',
  config: {
    tools: [{ functionDeclarations: [readFileTool.declaration] }],
    // thinking モデルのデフォルト有効な思考を無効化（ツール利用の安定性向上）
    thinkingConfig: { thinkingBudget: 0 },
  },
});

// 1回だけ送信する（ループなし）
const userMessage = 'package.json の name フィールドを教えて';
console.log(`You: ${userMessage}`);

const response = await chat.sendMessage({ message: userMessage });

console.log('\n--- response ---');
console.log('text        :', response.text);
console.log('functionCalls:', JSON.stringify(response.functionCalls, null, 2));
console.log('----------------\n');

if (response.functionCalls && response.functionCalls.length > 0) {
  const fc = response.functionCalls[0];
  console.log(`→ Gemini が "${fc.name}" を呼びたがっている`);
  console.log(`  args: ${JSON.stringify(fc.args)}`);

  // アプリ側でツールを実行
  const result = await readFileTool.execute(fc.args as { path: string });
  console.log(`  実行結果（先頭100文字）: ${result.slice(0, 100)}`);

  // 結果を Gemini に返す（この続きは step4 で）
  const toolResponse = createPartFromFunctionResponse(fc.id ?? '', fc.name ?? '', {
    output: result,
  });
  const finalResponse = await chat.sendMessage({ message: [toolResponse] });
  console.log(`\nGemini: ${finalResponse.text}`);
} else {
  console.log(`Gemini: ${response.text}`);
}

