      type: Type.OBJECT,
      properties: {
        path: { type: Type.STRING, description: "ファイルパス" },
      },
      required: ["path"],
    },
  },
  execute: async (args: { path: string }) => {
    return await fs.readFile(args.path, "utf-8");
  },
};

