  model: "gemini-2.5-flash-lite",
  config: {
    // declaration だけを Gemini に渡す
    tools: [{ functionDeclarations: [readFileTool.declaration] }],
    // gemini-2.5-flash-lite は thinking モデルのため、ツール応答が空になることがある
